/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; requeue puts a not-yet-finalized message back at the front of the
 * queue, restoring its position among the unfinished messages so per-key
 * enqueue order survives retries.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  return {
    enqueue(message) {
      entries.push({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue() {
      for (let i = 0; i < entries.length; i++) {
        if (!done.has(entries[i].id)) return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      // Front-insertion keeps a retrying message ahead of messages that were
      // enqueued after it. Appending at the tail would let a later message
      // with the same key overtake it and break per-key ordering.
      entries.unshift(message)
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

