/**
 * Delivery pump: dequeue → hold not-yet-due and same-key-blocked messages →
 * skip duplicates → process → emit + record + ack on success, or requeue with
 * backoff on failure.
 *
 * Guarantees implemented here:
 * - Effectively-once: the sink is told about a message only after
 *   processMessage accepts it, immediately before the message is finalized.
 *   A failed attempt therefore leaves no delivery record, so a retry can
 *   never re-deliver a message the downstream has already accepted.
 * - Per-key ordering: a message is never delivered while an earlier-enqueued
 *   message with the same key is still unfinished (awaiting retry), so
 *   same-key messages are delivered in enqueue order even across retries.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)
  return {
    run(steps = Infinity) {
      for (let step = 0; step < steps; step++) {
        // Scan the queue from the head for the next deliverable message.
        // Messages that are not due yet (retryAt in the future) or that share
        // their key with an already-held earlier message are held aside; they
        // are put back at the front of the queue (in reverse, restoring their
        // enqueue positions) before the step ends. Holding — instead of
        // appending held messages at the tail — is what keeps later same-key
        // messages from overtaking a retrying one.
        const held = []
        const heldKeys = new Set()
        let worked = false
        while (true) {
          const message = queue.dequeue()
          if (message === null) break
          const now = clock.now()
          const notDue = message.retryAt !== undefined && now < message.retryAt
          if (notDue || heldKeys.has(message.key)) {
            // Undeliverable for now: not due yet, or an earlier message with
            // the same key is still ahead of it. It blocks its key until it
            // is finalized (delivered or abandoned).
            heldKeys.add(message.key)
            held.push(message)
            continue
          }
          if (dedup.isDuplicate(message.id, now)) {
            // Already delivered inside the dedup window: finalize without
            // emitting a second time.
            queue.ack(message.id)
            continue
          }
          // Delivery attempt. The sink is notified only after processMessage
          // accepts the message, so a failed attempt records no delivery and
          // the eventual success records exactly one.
          let ok = false
          try {
            ok = processMessage(message)
          } catch {
            ok = false
          }
          if (!ok) {
            message.attempts += 1
            if (message.attempts >= maxAttempts) {
              queue.ack(message.id)
              sink.failed(message)
            } else {
              message.retryAt = retrier.scheduleRetry(message.attempts, clock.now())
              queue.requeue(message)
            }
            worked = true
            break
          }
          sink.emit(message)
          dedup.record(message.id, clock.now())
          queue.ack(message.id)
          worked = true
          break
        }
        for (let i = held.length - 1; i >= 0; i--) queue.requeue(held[i])
        if (!worked) break
      }
    },
  }
}

