// Scratch verification for the two authoritative guarantees under failure +
// retry paths. Run directly: node verify-guarantees.mjs (deleted afterwards;
// not part of the test suite).
import assert from 'node:assert/strict'
import { createQueue, retryWithBackoff, createDedup, createPump, createSink } from './src/index.js'

function mutableClock(start = 0) {
  return { t: start, now() { return this.t }, advance(ms) { this.t += ms } }
}

let pass = 0
function check(name, fn) {
  try {
    fn()
    pass++
    console.log(`✔ ${name}`)
  } catch (err) {
    console.log(`✘ ${name}\n  ${err.message}`)
    process.exitCode = 1
  }
}

// V1: effectively-once — attempt fails once, then succeeds: exactly one delivery.
check('V1 transient failure then success delivers exactly once', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => ++calls === 1 ? false : true,
  })
  clock.advance(1000) // past first backoff
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(calls, 2) // retry really happened
})

// V2: per-key order across a retry (old code let m2 overtake m1).
check('V2 same-key successor waits for retrying predecessor', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id === 'm1' && ++calls === 1 ? false : true,
  })
  pump.run(5) // m1 fails, backoff scheduled; m2 must not be delivered
  assert.deepEqual(sink.deliveredIds(), [])
  clock.advance(1000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
})

// V3: per-key order with two failed attempts on the predecessor.
check('V3 ordering holds across two retries', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  let m1Calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id === 'm1' ? ++m1Calls < 3 : true,
  })
  for (let i = 0; i < 4; i++) { pump.run(10); clock.advance(1000) }
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(m1Calls, 3) // 100ms, 200ms backoffs both honored
})

// V4: interleaved keys — other keys may flow while K1 waits, K1 order intact.
check('V4 other keys not blocked, same-key order preserved', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K2', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K1', payload: 3 })
  let m1Calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id === 'm1' ? ++m1Calls === 2 : true,
  })
  pump.run(20) // m1 fails once; m2 deliverable, m3 must wait for m1
  const mid = sink.deliveredIds()
  assert.deepEqual(mid.filter((id) => id === 'K1' && false), [])
  assert.equal(mid.includes('m3'), false) // m3 not delivered before m1
  assert.equal(mid.includes('m1'), false)
  clock.advance(1000)
  pump.run(20)
  const all = sink.deliveredIds()
  assert.equal(all.indexOf('m1'), all.indexOf('m3') - 1 || all.indexOf('m1') < all.indexOf('m3') ? all.indexOf('m1') < all.indexOf('m3') : false, `K1 order broken: ${all}`)
  assert.ok(all.indexOf('m1') < all.indexOf('m3'), `K1 order broken: ${all}`)
})

// V5: backoff honored — retrying message stays queued until retryAt.
check('V5 retry waits for backoff; distinct key flows meanwhile', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K2', payload: 2 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id !== 'm1',
  })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2']) // m2 not blocked by m1's backoff
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2', 'm1'])
})

// V6: permanent failure — never delivered, reported failed, key unblocked.
check('V6 exhausted attempts: no delivery, failed reported, key unblocked', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock, maxAttempts: 3,
    processMessage: () => { calls++; return false },
  })
  clock.advance(100); pump.run(10)
  clock.advance(300); pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [])
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(calls, 3)
  clock.advance(1000); pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2']) // successor delivered after abandonment
})

// V7: duplicate id re-enqueued while first copy is mid-retry — one delivery.
check('V7 duplicate id with first copy retrying yields one delivery', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => ++calls === 1 ? false : true,
  })
  clock.advance(1000)
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

// V8: message enqueued AFTER a same-key message started retrying still waits.
check('V8 later-enqueued same-key message cannot overtake retrying one', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let fail = true
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => {
      if (m.id === 'm1' && fail) { queue.enqueue({ id: 'm2', key: 'K', payload: 2 }); fail = false; return false }
      return true
    },
  })
  pump.run(5)
  assert.deepEqual(sink.deliveredIds(), [])
  clock.advance(1000)
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

// V9: unbounded run() terminates while everything is blocked by backoff.
check('V9 run() terminates when all messages are in backoff', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => false,
  })
  pump.run(2)
  clock.advance(0)
  pump.run() // must terminate, not spin
  assert.deepEqual(sink.deliveredIds(), [])
})

// V10: throwing processMessage is treated as a failed attempt, message survives.
check('V10 thrown delivery error retries without losing the message', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => { calls++; if (calls === 1) throw new Error('downstream'); return true },
  })
  clock.advance(1000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(calls, 2)
})

// V11: dedup window still functions through the pump (in-window suppress,
// post-window allows re-delivery by design).
check('V11 dedup window semantics unchanged via pump', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  const dedup = createDedup({ windowMs: 100 })
  const pump = createPump({ queue, dedup, sink, clock, processMessage: () => true })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  clock.advance(50)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1']) // in-window duplicate suppressed
  clock.advance(200)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm1']) // window expired: allowed again
})

