    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => {
      if (m.id === 'm1') { m1Tries++; return m1Tries > 1 }
      return true
    },
  })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2']) // m2 not blocked by m1's backoff
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2', 'm1'])
  assert.equal(m1Tries, 2)
})

// V6: permanent failure — never delivered, reported failed, key unblocked.
check('V6 exhausted attempts: no delivery, failed reported, key unblocked', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock, maxAttempts: 3,
    processMessage: () => { calls++; return false },
  })
  pump.run(10)                     // attempt 1 -> retryAt = 100
  clock.advance(1000); pump.run(10) // attempt 2 -> retryAt = +200
  clock.advance(1000); pump.run(10) // attempt 3 -> abandoned
  assert.deepEqual(sink.deliveredIds(), [])
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(calls, 3)
  clock.advance(1000); pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2']) // successor delivered after abandonment
})

// V7: duplicate id re-enqueued while first copy is mid-retry — one delivery.
check('V7 duplicate id with first copy retrying yields one delivery', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => ++calls === 1 ? false : true,
  })
  pump.run(5) // m1 fails; second copy held behind it (same key)
  clock.advance(1000)
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
})

// V8: message enqueued AFTER a same-key message started retrying still waits.
check('V8 later-enqueued same-key message cannot overtake retrying one', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let fail = true
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => {
      if (m.id === 'm1' && fail) { queue.enqueue({ id: 'm2', key: 'K', payload: 2 }); fail = false; return false }
      return true
    },
  })
  pump.run(5)
  assert.deepEqual(sink.deliveredIds(), [])
  clock.advance(1000)
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
})

// V9: unbounded run() terminates while everything is blocked by backoff.
check('V9 run() terminates when all messages are in backoff', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => false,
  })
  pump.run(2)
  pump.run() // must terminate, not spin
  assert.deepEqual(sink.deliveredIds(), [])
})

// V10: throwing processMessage is treated as a failed attempt, message survives.
check('V10 thrown delivery error retries without losing the message', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => { calls++; if (calls === 1) throw new Error('downstream'); return true },
  })
  pump.run(10) // attempt 1 throws -> caught, treated as failure
  assert.deepEqual(sink.deliveredIds(), [])
  clock.advance(1000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  assert.equal(calls, 2)
})

// V11: through the pump, a delivered id is never re-delivered: within the
// dedup window by the dedup guard, and afterwards because ack finalizes the
// id in the queue (at-most-once is absolute, stronger than the window).
check('V11 duplicate id is never re-delivered through the pump', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100 }), sink, clock, processMessage: () => true,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  clock.advance(50)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1']) // in-window duplicate suppressed
  clock.advance(200)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1']) // finalized id stays delivered-once
})

// V12: multi-key stress — order per key under random-ish failures, one drain.
check('V12 multi-key stress: per-key order survives interleaved retries', () => {
  const queue = createQueue()
  const sink = createSink()
  const clock = mutableClock()
  const ids = ['a1', 'b1', 'a2', 'c1', 'b2', 'a3', 'c2', 'b3']
  for (const id of ids) queue.enqueue({ id, key: id[0], payload: id })
  let attempt = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000000 }), sink, clock, maxAttempts: 10,
    processMessage: (m) => {
      attempt++
      return !(m.id === 'a1' && attempt === 1) &&
             !(m.id === 'b1' && attempt === 3) &&
             !(m.id === 'c1' && attempt === 5)
    },
  })
  for (let i = 0; i < 8; i++) { pump.run(50); clock.advance(1000) }
  const got = sink.deliveredIds()
  for (const k of ['a', 'b', 'c']) {
    const idx = got.filter((id) => id[0] === k).map((id) => ids.indexOf(id))
    assert.deepEqual(idx, [ids.indexOf(k + '1'), ids.indexOf(k + '2'), ids.indexOf(k + '3')], `key ${k} order: ${got}`)
  }
  assert.equal(sink.hasDuplicate(), false)
  assert.deepEqual(sink.failedIds(), [])
  assert.deepEqual([...got].sort(), [...ids].sort()) // everything delivered exactly once
})

